import { readdir, readFile, writeFile, mkdir, cp } from "node:fs/promises";
import { marked } from "marked";

// Every page ships twice: rendered HTML at /<slug>/ and the raw markdown at /<slug>.md, so an
// agent can fetch the markdown without paying for the nav, the banner and the footer.
const files = (await readdir("content")).filter((f) => f.endsWith(".md"));

for (const file of files) {
  const slug = file.replace(/\.md$/, "");
  const src = await readFile(`content/${file}`, "utf8");
  await mkdir(`dist/${slug}`, { recursive: true });
  await writeFile(`dist/${slug}/index.html`, `<!doctype html><title>${slug}</title>${marked(src)}`);
  await writeFile(`dist/${slug}.md`, src);
}

await cp("public", "dist", { recursive: true });

import { readdir, readFile, writeFile, mkdir, cp } from "node:fs/promises";
import { marked } from "marked";

// content/**.md and pages/**.md render to dist/<path>/index.html; public/ is copied verbatim,
// so anything that has to be served at the site root belongs in public/.
async function render(dir) {
  for (const entry of await readdir(dir, { withFileTypes: true, recursive: true })) {
    if (!entry.isFile() || !entry.name.endsWith(".md")) continue;
    const src = `${entry.parentPath}/${entry.name}`;
    const out = `dist/${src.replace(/^(content|pages)\//, "").replace(/\.md$/, "")}`;
    await mkdir(out, { recursive: true });
    await writeFile(`${out}/index.html`, marked(await readFile(src, "utf8")));
  }
}

await render("content");
await render("pages");
await cp("public", "dist", { recursive: true });
